<?php
require_once __DIR__ . '/../config/database.php';
require_once __DIR__ . '/../includes/auth.php';
require_admin();
$pdo = db(); $error=''; $success=''; $editResult=null;
$subjects=['php'=>'PHP','dbms'=>'DBMS','computer_network'=>'Computer Network','operating_system'=>'Operating System','computer_graphics'=>'Computer Graphics'];
if($_SERVER['REQUEST_METHOD']==='POST'){
    $action=$_POST['action']??'';
    try{
        if($action==='save'){
            $id=(int)($_POST['id']??0); $studentId=(int)($_POST['student_id']??0); $marks=[];
            foreach(array_keys($subjects) as $subject){$value=filter_var($_POST[$subject]??null,FILTER_VALIDATE_INT); if($value===false||$value<0||$value>100) throw new RuntimeException('Each mark must be between 0 and 100.'); $marks[$subject]=$value;}
            if(!$studentId) throw new RuntimeException('Please select a student.');
            $calc=calculate_result(array_values($marks));
            if($id){$sql='update results set student_id=:student_id, php=:php, dbms=:dbms, computer_network=:computer_network, operating_system=:operating_system, computer_graphics=:computer_graphics, total=:total, percentage=:percentage, grade=:grade, status=:status, updated_at=now() where id=:id'; $stmt=$pdo->prepare($sql); $stmt->execute(array_merge(['student_id'=>$studentId],$marks,$calc,['id'=>$id])); $success='Result updated successfully.';}
            else{$sql='insert into results (student_id,php,dbms,computer_network,operating_system,computer_graphics,total,percentage,grade,status) values (:student_id,:php,:dbms,:computer_network,:operating_system,:computer_graphics,:total,:percentage,:grade,:status)'; $stmt=$pdo->prepare($sql); $stmt->execute(array_merge(['student_id'=>$studentId],$marks,$calc)); $success='Result added successfully.';}
        }elseif($action==='delete'){$stmt=$pdo->prepare('delete from results where id=:id');$stmt->execute(['id'=>(int)$_POST['id']]);$success='Result deleted successfully.';}
    }catch(Throwable $e){$error=$e->getCode()==='23505'?'This student already has a result.':$e->getMessage();}
}
if(isset($_GET['edit'])){$stmt=$pdo->prepare('select * from results where id=:id');$stmt->execute(['id'=>(int)$_GET['edit']]);$editResult=$stmt->fetch();}
$students=$pdo->query('select id,name,roll_number from students order by name')->fetchAll();
$search=trim($_GET['q']??'');
if($search!==''){$stmt=$pdo->prepare('select r.*,s.name,s.roll_number from results r join students s on s.id=r.student_id where s.name ilike :q or s.roll_number ilike :q order by r.id desc');$stmt->execute(['q'=>"%{$search}%"]);$results=$stmt->fetchAll();}
else{$results=$pdo->query('select r.*,s.name,s.roll_number from results r join students s on s.id=r.student_id order by r.id desc')->fetchAll();}
$drawerOpen=isset($_GET['edit'])||$error!=='';
?>
