th:54px;height:54px;margin:0 auto 15px;border-radius:16px;display:grid;place-items:center;background:rgba(37,99,235,.08);font-size:24px}.results-page .empty-state h3{margin:0 0 8px}.results-page .empty-state p{max-width:470px;margin:0 auto 20px;opacity:.7}.results-page .drawer{position:fixed;inset:0;z-index:1000;visibility:hidden;pointer-events:none}.results-page .drawer.open{visibility:visible;pointer-events:auto}.results-page .drawer-backdrop{position:absolute;inset:0;background:rgba(15,23,42,.46);opacity:0;transition:opacity .2s}.results-page .drawer.open .drawer-backdrop{opacity:1}.results-page .drawer-panel{position:absolute;right:0;top:0;height:100%;width:min(520px,100%);background:var(--card-bg,#fff);box-shadow:-18px 0 50px rgba(15,23,42,.18);transform:translateX(100%);transition:transform .25s;display:flex;flex-direction:column}.results-page .drawer.open .drawer-panel{transform:translateX(0)}.results-page .drawer-header{padding:22px 24px;border-bottom:1px solid rgba(100,116,139,.14);display:flex;justify-content:space-between;gap:16px;align-items:flex-start}.results-page .drawer-header h2{margin:0 0 4px;font-size:21px}.results-page .drawer-header p{margin:0;opacity:.65;font-size:13px}.results-page .drawer-close{width:38px;height:38px;border:0;border-radius:10px;background:rgba(100,116,139,.08);cursor:pointer;font-size:22px}.results-page .drawer-body{padding:22px 24px 110px;overflow-y:auto}.results-page .form-section{margin-bottom:25px}.results-page .section-label{margin:0 0 13px;font-size:11px;letter-spacing:.09em;text-transform:uppercase;opacity:.58;font-weight:800}.results-page .field-label{display:block;font-weight:700;margin-bottom:7px}.results-page .field-help{display:block;margin-top:6px;font-size:12px;opacity:.58}.results-page .marks-grid{display:grid;gap:13px}.results-page .mark-field{position:relative}.results-page .max-mark{position:absolute;right:13px;top:38px;font-size:12px;opacity:.5;pointer-events:none}.results-page .mark-input{padding-right:64px!important}.results-page .mark-meter{height:4px;margin-top:7px;border-radius:999px;background:rgba(100,116,139,.12);overflow:hidden}.results-page .mark-meter span{display:block;height:100%;width:0;background:#2563eb;transition:width .15s}.results-page .performance-card{border:1px solid rgba(37,99,235,.14);background:rgba(37,99,235,.045);border-radius:16px;padding:17px}.results-page .performance-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.results-page .performance-item span{display:block;font-size:11px;text-transform:uppercase;letter-spacing:.06em;opacity:.55;font-weight:800;margin-bottom:3px}.results-page .performance-item strong{font-size:18px}.results-page .drawer-footer{position:absolute;bottom:0;left:0;right:0;padding:15px 24px;background:var(--card-bg,#fff);border-top:1px solid rgba(100,116,139,.14);display:flex;justify-content:flex-end;gap:10px}.results-page .confirm{position:fixed;inset:0;z-index:1100;display:grid;place-items:center;padding:20px;background:rgba(15,23,42,.48);opacity:0;visibility:hidden;pointer-events:none;transition:all .18s}.results-page .confirm.open{opacity:1;visibility:visible;pointer-events:auto}.results-page .confirm-card{width:min(430px,100%);background:var(--card-bg,#fff);border-radius:18px;padding:24px;box-shadow:0 24px 70px rgba(15,23,42,.25)}.results-page .confirm-card h3{margin:0 0 8px}.results-page .confirm-card p{margin:0;opacity:.68;line-height:1.55}.results-page .confirm-actions{display:flex;justify-content:flex-end;gap:10px;margin-top:22px}.results-page .danger-btn{border:0;border-radius:10px;padding:11px 15px;background:#dc2626;color:#fff;font-weight:800;cursor:pointer}.results-page .alert{display:flex;align-items:center;gap:9px}.results-page .alert-close{margin-left:auto;border:0;background:transparent;cursor:pointer;font-size:18px;opacity:.6}
@media(max-width:850px){.results-page .admin-layout{display:block;min-height:100vh}.results-page .admin-sidebar{position:fixed;left:0;right:0;bottom:0;z-index:100;padding:0;background:#0f172a;border-top:0;box-shadow:none;backdrop-filter:none}.results-page .admin-sidebar .brand,.results-page .admin-nav-label{display:none}.results-page .admin-sidebar nav{display:grid;grid-template-columns:repeat(4,1fr);gap:0}.results-page .admin-sidebar nav a{min-height:64px;justify-content:center;flex-direction:column;gap:4px;padding:8px 3px;border-radius:0;font-size:10px}.results-page .admin-sidebar nav a svg{width:17px;height:17px}.results-page .admin-sidebar nav a.active{box-shadow:inset 0 2px 0 #60a5fa}.results-page .admin-sidebar nav a.logout-link{margin-top:0}.results-page .search-box{max-width:none}.results-page .table-wrap{overflow-x:hidden}.results-page .table-wrap table{display:block;width:100%}.results-page .table-wrap thead{display:none}.results-page .table-wrap tbody,.results-page .table-wrap tr{display:block;width:100%;max-width:100%}.results-page .table-wrap tr{box-sizing:border-box;padding:14px;margin-bottom:12px;border:1px solid rgba(100,116,139,.14);border-radius:16px;background:var(--card-bg,#fff);overflow:hidden}.results-page .table-wrap td{display:flex;justify-content:space-between;gap:12px;align-items:center;box-sizing:border-box;width:100%;min-width:0;padding:8px 0;border:0}.results-page .table-wrap td:before{content:attr(data-label);font-size:10px;text-transform:uppercase;letter-spacing:.05em;opacity:.5;font-weight:800;flex:0 0 auto}.results-page .table-wrap td:first-child{display:block;padding:0 0 10px;max-width:100%}.results-page .table-wrap td:first-child:before{display:none}.results-page .student-cell{width:100%;min-width:0;max-width:100%;gap:10px}.results-page .student-cell>span:last-child{min-width:0;max-width:calc(100% - 48px)}.results-page .student-cell strong{font-size:13px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.results-page .student-cell small{font-size:10px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.results-page .student-avatar{width:34px;height:34px;border-radius:10px}.results-page .score-main,.results-page .percentage-cell{white-space:nowrap}.results-page .row-actions{gap:6px}.results-page .drawer-body{padding-left:18px;padding-right:18px}.results-page .drawer-header,.results-page .drawer-footer{padding-left:18px;padding-right:18px}.results-page .admin-main{padding-bottom:112px}.results-page .table-wrap td[data-label="Actions"]{display:block;padding:11px 0 0}.results-page .table-wrap td[data-label="Actions"]:before{display:none}.results-page .row-actions{display:grid;grid-template-columns:1fr 1fr;width:100%;gap:8px}.results-page .icon-action{width:100%;height:42px;min-width:0;touch-action:manipulation;position:relative;z-index:2;font-size:0}.results-page .icon-action::after{font-size:11px;font-weight:800}.results-page .icon-action[title="Edit result"]::after{content:"Edit Result"}.results-page .icon-action[title="Delete result"]::after{content:"Delete";color:#dc2626}}
@media(max-width:600px){.results-page .admin-main{padding-left:12px;padding-right:12px;padding-bottom:116px}.results-page .page-heading{align-items:flex-start;gap:16px}.results-page .page-heading .btn{width:100%}.results-page .table-wrap tr{padding:13px;width:100%;margin-left:0;margin-right:0}.results-page .table-wrap td{font-size:12px}.results-page .student-cell{gap:9px}.results-page .student-avatar{width:32px;height:32px}.results-page .student-cell>span:last-child{max-width:calc(100% - 43px)}.results-page .drawer-panel{width:100%}}
