</style></head><body><div class="admin-layout results-page"><aside class="sidebar admin-sidebar"><a class="brand" href="../index.php">Result <span>System</span></a><nav aria-label="Admin navigation"><p class="admin-nav-label">Main</p><a href="dashboard.php"><svg aria-hidden="true" viewBox="0 0 24 24"><path d="M4 4h6v6H4zM14 4h6v6h-6zM4 14h6v6H4zM14 14h6v6h-6z"/></svg><span>Dashboard</span></a><a href="students.php"><svg aria-hidden="true" viewBox="0 0 24 24"><path d="M16 20v-1.5a3.5 3.5 0 0 0-3.5-3.5h-5A3.5 3.5 0 0 0 4 18.5V20M10 11a3.5 3.5 0 1 0 0-7 3.5 3.5 0 0 0 0 7ZM16 4.2a3.5 3.5 0 0 1 0 6.6M17 15h1a3 3 0 0 1 3 3v2"/></svg><span>Students</span></a><a class="active" href="results.php" aria-current="page"><svg aria-hidden="true" viewBox="0 0 24 24"><path d="M7 3h8l4 4v14H7zM15 3v5h5M10 12h6M10 16h6"/></svg><span>Results</span></a><p class="admin-nav-label account-label">Account</p><a href="logout.php" class="logout-link"><svg aria-hidden="true" viewBox="0 0 24 24"><path d="M10 5H5v14h5M14 8l4 4-4 4M9 12h9"/></svg><span>Logout</span></a></nav></aside><main class="admin-main"><div class="page-heading"><div><p class="eyebrow">Administration</p><h1>Result Management</h1><p class="muted">Create, update and manage student academic results.</p></div><?php if($students):?><button class="btn btn-primary" type="button" onclick="openDrawer('add')">+ Add Result</button><?php endif;?></div><?php if($success):?><div class="alert success" data-auto-dismiss><span>✓</span><span><?=e($success)?></span><button class="alert-close" type="button">×</button></div><?php endif;?><?php if($error&&!$drawerOpen):?><div class="alert error"><span>!</span><span><?=e($error)?></span><button class="alert-close" type="button">×</button></div><?php endif;?><?php if(!$students):?><section class="panel empty-state"><div class="empty-icon">🎓</div><h3>Add a student first</h3><p>Results can only be added for existing students.</p><a class="btn btn-primary" href="students.php">Manage Students</a></section><?php else:?><div class="page-toolbar"><form class="search-box" method="get" action="results.php"><span class="search-icon">⌕</span><input name="q" value="<?=e($search)?>" placeholder="Search by student name or roll number..." aria-label="Search results" type="search"><?php if($search!==''):?><a class="clear-search" href="results.php" aria-label="Clear search">×</a><?php endif;?></form></div><p class="result-count"><?=count($results)?> <?=count($results)===1?'Result':'Results'?><?= $search!==''?' found':''?></p><section class="panel table-wrap"><?php if(!$results):?><div class="empty-state"><div class="empty-icon">⌕</div><h3><?=$search!==''?'No matching results':'No results yet'?></h3><p><?=$search!==''?'We could not find a result matching “'.e($search).'”.':'Add a result for a student to start building the academic record.'?></p><?php if($search!==''):?><a class="btn btn-secondary" href="results.php">Clear Search</a><?php else:?><button class="btn btn-primary" type="button" onclick="openDrawer('add')">+ Add Result</button><?php endif;?></div><?php else:?><table><thead><tr><th>Student</th><th>Roll No.</th><th>Score</th><th>Percentage</th><th>Grade</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($results as $r):$clean=preg_replace('/[^A-Za-z]/','',$r['name']);$initials=strtoupper(substr($clean,0,2));if($initials==='')$initials='ST';?><tr><td data-label="Student"><div class="student-cell"><span class="student-avatar"><?=e($initials)?></span><span><strong><?=e($r['name'])?></strong><small><?=e($r['roll_number'])?></small></span></div></td><td data-label="Roll No."><?=e($r['roll_number'])?></td><td data-label="Score"><span class="score-main"><?=e((string)$r['total'])?></span> <span class="score-max">/ 500</span></td><td data-label="Percentage" class="percentage-cell"><?=number_format((float)$r['percentage'],1)?>%</td><td data-label="Grade"><span class="grade-badge"><?=e($r['grade'])?></span></td><td data-label="Status"><span class="status-badge <?= $r['status']==='PASS'?'pass':'fail' ?>"><span class="status-dot"></span><?=e($r['status'])?></span></td><td data-label="Actions"><div class="row-actions"><button class="icon-action" type="button" title="Edit result" onclick="openDrawer('edit',<?=e((string)$r['id'])?>)">✎</button><button class="icon-action" type="button" title="Delete result" onclick='openDelete(<?=e((string)$r["id"])?>,<?=json_encode($r["name"])?>)'>⌫</button></div></td></tr><?php endforeach;?></tbody></table><?php endif;?></section><?php endif;?></main>
<div class="drawer <?=$drawerOpen?'open':''?>" id="resultDrawer"><div class="drawer-backdrop" onclick="closeDrawer()"></div><aside class="drawer-panel" role="dialog" aria-modal="true" aria-labelledby="drawerTitle"><div class="drawer-header"><div><h2 id="drawerTitle"><?=$editResult?'Edit Result':'Add Result'?></h2><p><?=$editResult?'Update academic marks for '.e($editResult['name']??'the student').'.':'Create a new academic result.'?></p></div><button class="drawer-close" type="button" onclick="closeDrawer()" aria-label="Close">×</button></div><form method="post" id="resultForm" class="drawer-body"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e((string)($editResult['id']??''))?>"><?php if($error):?><div class="alert error"><span>!</span><span><?=e($error)?></span></div><?php endif;?><section class="form-section"><h3 class="section-label">Student</h3><label class="field-label" for="student_id">Student</label><select id="student_id" name="student_id" required><option value="">Select student</option><?php foreach($students as $s):?><option value="<?=$s['id']?>" <?=((int)($editResult['student_id']??0)===(int)$s['id'])?'selected':''?>><?=e($s['name'])?> — <?=e($s['roll_number'])?></option><?php endforeach;?></select><span class="field-help">Choose the student whose academic marks you want to record.</span></section><section class="form-section"><h3 class="section-label">Subject Marks</h3><div class="marks-grid"><?php foreach($subjects as $field=>$label):$value=$editResult[$field]??'';?><div class="mark-field"><label class="field-label" for="<?=$field?>"><?=e($label)?></label><input class="mark-input" id="<?=$field?>" name="<?=$field?>" type="number" min="0" max="100" step="1" inputmode="numeric" value="<?=e((string)$value)?>" placeholder="0" required><span class="max-mark">/ 100</span><div class="mark-meter"><span data-meter="<?=$field?>"></span></div><span class="field-help">Enter marks between 0 and 100.</span></div><?php endforeach;?></div></section><section class="form-section"><h3 class="section-label">Performance Preview</h3><div class="performance-card"><div class="performance-grid"><div class="performance-item"><span>Total</span><strong id="previewTotal">0 / 500</strong></div><div class="performance-item"><span>Percentage</span><strong id="previewPercentage">0.0%</strong></div><div class="performance-item"><span>Grade</span><strong id="previewGrade">—</strong></div><div class="performance-item"><span>Status</span><strong id="previewStatus">—</strong></div></div></div></section></form><div class="drawer-footer"><button class="btn btn-secondary" type="button" onclick="closeDrawer()">Cancel</button><button class="btn btn-primary" type="submit" form="resultForm"><?=$editResult?'Save Changes':'Save Result'?></button></div></aside></div>
<div class="confirm" id="deleteDialog"><div class="confirm-card"><h3>Delete this result?</h3><p id="deleteDescription">This will permanently remove this student's academic result. This action cannot be undone.</p><div class="confirm-actions"><button class="btn btn-secondary" type="button" onclick="closeDelete()">Cancel</button><form method="post"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" id="deleteId"><button class="danger-btn" type="submit">Delete Result</button></form></div></div></div></div>
<script>
(function(){const drawer=document.getElementById('resultDrawer'),body=document.body,fields=['php','dbms','computer_network','operating_system','computer_graphics'];function preview(){let total=0,filled=0;fields.forEach(k=>{const i=document.getElementById(k),m=document.querySelector('[data-meter="'+k+'"]'),v=Math.max(0,Math.min(100,Number(i?.value)||0));total+=v;if(i?.value!=='')filled++;if(m)m.style.width=v+'%'});const p=total/5;let g='—',s='—';if(filled){g=p>=90?'A+':p>=80?'A':p>=70?'B':p>=60?'C':p>=50?'D':'F';s=p>=40?'PASS':'FAIL'}document.getElementById('previewTotal').textContent=Math.round(total)+' / 500';document.getElementById('previewPercentage').textContent=p.toFixed(1)+'%';document.getElementById('previewGrade').textContent=g;document.getElementById('previewStatus').textContent=s}fields.forEach(k=>document.getElementById(k)?.addEventListener('input',preview));preview();window.openDrawer=function(mode,id){if(mode==='edit'){location.href='results.php?edit='+id;return}drawer.classList.add('open');body.classList.add('modal-open');setTimeout(()=>document.getElementById('student_id')?.focus(),80)};window.closeDrawer=function(){if(new URLSearchParams(location.search).has('edit'))location.href='results.php';else{drawer.classList.remove('open');body.classList.remove('modal-open')}};window.openDelete=function(id,name){document.getElementById('deleteId').value=id;document.getElementById('deleteDescription').textContent='This will permanently remove '+name+'\'s academic result. This action cannot be undone.';document.getElementById('deleteDialog').classList.add('open');body.classList.add('modal-open')};window.closeDelete=function(){document.getElementById('deleteDialog').classList.remove('open');body.classList.remove('modal-open')};document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(document.getElementById('deleteDialog').classList.contains('open'))closeDelete();else if(drawer.classList.contains('open'))closeDrawer()}});document.querySelectorAll('.alert-close').forEach(b=>b.onclick=()=>b.closest('.alert').remove());document.querySelectorAll('[data-auto-dismiss]').forEach(a=>setTimeout(()=>a.isConnected&&a.remove(),4500))})();
</script></body></html>